What does this program print?

```cpp
#include <print>

template <typename... Ts>
auto right_fold(Ts... xs) { return (xs - ...); }

template <typename... Ts>
auto left_fold(Ts... xs) { return (... - xs); }

int main() {
    std::println("{} {}", right_fold(10, 4, 3), left_fold(10, 4, 3));
}
```

What does this program print?

```cpp
#include <print>

template <typename T>
void show(T) { std::print("generic "); }

template <>
void show<int>(int) { std::print("int "); }

void show(double) { std::print("plain-double "); }

int main() {
    show(1);
    show(1.0);
    show('c');
    show(2.0f);
    std::println("");
}
```

